<script>
import moment from 'moment'

export default {
  name: 'MemberSettings',
  emits: ['save', 'close', 'remove'],
  props: {
    member: { type: Object, required: true }
  },
  data() {
    return { draft: {} }
  },
  created() {
    this.draft = { ...this.member }
  },
  computed: {
    joinedLabel() {
      return this.draft.joinedAt ? moment(this.draft.joinedAt).fromNow() : 'recently'
    }
  },
  methods: {
    save() {
      this.$emit('save', { ...this.draft })
    }
  }
}
</script>
