        @close="editingCategory = null"
      />
    </modal>

    <!-- Member settings -->
    <modal close="true" @close="selectedMember = null" v-if="selectedMember">
      <MemberSettings
        :member="selectedMember"
        @save="onSaveMember"
        @remove="onRemoveMember"
        @close="selectedMember = null"
      />
    </modal>

    <!-- Add member -->
    <modal v-if="showAddMember && activeTeam">
      <AddMemberDialog
        :team="activeTeam"
        @added="onMemberAdded"
        @close="showAddMember = false"
      />
    </modal>
  </div>
</template>

<script>
export default {
  name: 'TeamView',
  props: ['params'],
  data() {
    return {
      // UI state
      channelSearch: '',
      messageSearch: '',
      showChannelSearch: false,
      showMembers: false,
      showMediaManager: false,
      dmCollapsed: false,
      // Modals
      showCreateTeam: false,
      showCreateChannel: false,
      showTeamSettings: false,
      showAddMember: false,
      createChannelCategoryId: null,
      editingChannel: null,
      editingChannelCategory: null,
      editingCategory: null,
      selectedMember: null,
      // Active chats
      activeChannelChat: null,
      activeDmChat: null
    }
  },
  created() {
    this.$storex.teams.init()
    this.$storex.media.init()
    if (this.activeChannel?.chatId) {
      this.loadChannelChat(this.activeChannel)
    }
    if (this.activeDmMember) {
      this.loadDmChat(this.activeDmMember)
    }
  },
  computed: {
    teams() {
      return this.$storex.teams.teams
    },
    activeTeam() {
      return this.$storex.teams.activeTeam
    },
    activeChannel() {
      return this.$storex.teams.activeChannel
    },
    activeDmMember() {
      return this.$storex.teams.activeDmMember
    },
    userInitial() {
      return this.$users.user?.username?.[0]?.toUpperCase() || '?'
    },
    filteredCategories() {
      if (!this.activeTeam) return []
      const cats = this.activeTeam.categories || []
      if (!this.channelSearch) return cats
      const q = this.channelSearch.toLowerCase()
      return cats.map(cat => ({
        ...cat,
        channels: cat.channels.filter(c => c.name.toLowerCase().includes(q))
      })).filter(cat => cat.channels.length)
    }
  },
  watch: {
    activeChannel(ch) {
      if (ch?.chatId) {
        this.loadChannelChat(ch)
      } else {
        this.activeChannelChat = null
      }
    },
    activeDmMember(member) {
      if (member) {
        this.loadDmChat(member)
      } else {
        this.activeDmChat = null
      }
    }
  },
  methods: {
    // ── Team actions ─────────────────────────────────────────────────────────
    selectTeam(teamId) {
      this.$storex.teams.selectTeam(teamId)
      this.activeChannelChat = null
      this.activeDmChat = null
    },

    onTeamCreated() {
      this.showCreateTeam = false
    },

    onSaveTeam(updated) {
      this.$storex.teams.updateTeam(updated)
      this.showTeamSettings = false
    },

    onDeleteTeam(teamId) {
      this.$storex.teams.deleteTeam(teamId)
      this.showTeamSettings = false
    },

    // ── Category actions ──────────────────────────────────────────────────────
    addCategory() {
      if (!this.activeTeam) return
      this.$storex.teams.createCategory({ teamId: this.activeTeam.id, name: 'New Category' })
    },

    editCategory(category) {
      this.editingCategory = { ...category }
    },

    toggleCategory(categoryId) {
      if (!this.activeTeam) return
      this.$storex.teams.toggleCategoryCollapsed({ teamId: this.activeTeam.id, categoryId })
    },

    onSaveCategory(updated) {
      this.$storex.teams.updateCategory({ teamId: this.activeTeam.id, category: updated })
      this.editingCategory = null
    },

    onDeleteCategory() {
      if (!this.editingCategory) return
      this.$storex.teams.deleteCategory({ teamId: this.activeTeam.id, categoryId: this.editingCategory.id })
      this.editingCategory = null
    },

    // ── Channel actions ───────────────────────────────────────────────────────
    openCreateChannel(categoryId = null) {
      this.createChannelCategoryId = categoryId || this.activeTeam?.categories[0]?.id || null
      this.showCreateChannel = true
    },

    async onChannelCreated(channel) {
      this.showCreateChannel = false
      await this.selectChannel(channel, this.findCategoryForChannel(channel.id))
    },

    async selectChannel(channel, category) {
      await this.$storex.teams.selectChannel({ teamId: this.activeTeam.id, channelId: channel.id })
      this.activeDmChat = null
      await this.loadChannelChat(channel)
    },

    async loadChannelChat(channel) {
      if (!channel?.chatId) { this.activeChannelChat = null; return }
      const cached = this.$chats.chats[channel.chatId]
      if (cached) {
        this.activeChannelChat = cached
      } else {
        const loaded = await this.$chats.loadChat({ id: channel.chatId })
        this.activeChannelChat = this.$chats.chats[channel.chatId] || loaded
      }
    },

    editChannel(channel, category) {
      this.editingChannel = { ...channel }
      this.editingChannelCategory = category
    },

    onSaveChannel(updated) {
      this.$storex.teams.updateChannel({
        teamId: this.activeTeam.id,
        categoryId: this.editingChannelCategory?.id || updated.categoryId,
        channel: updated
      })
      this.editingChannel = null
    },

    onDeleteChannel() {
      if (!this.editingChannel) return
      this.$storex.teams.deleteChannel({
        teamId: this.activeTeam.id,
        categoryId: this.editingChannelCategory?.id || this.editingChannel.categoryId,
        channelId: this.editingChannel.id
      })
      this.editingChannel = null
      this.activeChannelChat = null
    },

    findCategoryForChannel(channelId) {
      return this.activeTeam?.categories.find(cat =>
        cat.channels.some(ch => ch.id === channelId)
      ) || null
    },

    // ── DM actions ────────────────────────────────────────────────────────────
    async openDm(member) {
      const chatId = await this.$storex.teams.openDirectMessage({
        teamId: this.activeTeam.id,
        member
      })
      await this.loadDmChat(member, chatId)
    },

    async loadDmChat(member, chatId = null) {
      // Resolve chatId from store if not provided
      const team = this.activeTeam
      const resolvedChatId = chatId || (team?.directMessages || {})[member.id]
      if (!resolvedChatId) { this.activeDmChat = null; return }
      const cached = this.$chats.chats[resolvedChatId]
      if (cached) {
        this.activeDmChat = cached
      } else {
        const loaded = await this.$chats.loadChat({ id: resolvedChatId })
        this.activeDmChat = this.$chats.chats[resolvedChatId] || loaded
      }
    },

    // ── Member actions ────────────────────────────────────────────────────────
    onMemberAdded() {
      this.showAddMember = false
    },

    onSaveMember(updated) {
      this.$storex.teams.updateMember({ teamId: this.activeTeam.id, member: updated })
      this.selectedMember = null
    },

    onRemoveMember() {
      if (!this.selectedMember || !this.activeTeam) return
      this.$storex.teams.removeMember({ teamId: this.activeTeam.id, memberId: this.selectedMember.id })
      this.selectedMember = null
      if (this.activeDmMember?.id === this.selectedMember?.id) {
        this.activeDmChat = null
      }
    },

    // ── UI helpers ────────────────────────────────────────────────────────────
    statusColor(status) {
      return { online: 'bg-success', away: 'bg-warning', busy: 'bg-error', offline: 'bg-base-content/30' }[status] || 'bg-base-content/30'
    },

    statusBadgeClass(status) {
      return { online: 'badge-success', away: 'badge-warning', busy: 'badge-error', offline: 'badge-ghost' }[status] || 'badge-ghost'
    }
  }
}
</script>
```

Here's a summary of all changes made:

### New Files
- **`MemberAvatar.vue`** — Reusable avatar component with deterministic color generation from username and status dot indicator
- **`AddMemberDialog.vue`** — Clean dialog to add a member with username, role selection, and live preview

### Modified Files

**`src/store/teams.js`**
- Added `directMessages: {}` field to team factory (maps `memberId → chatId`)
- Added `activeDmMemberId` state field
- Added `setActiveDmMemberId` mutation that clears `activeChannelId` when switching to DM
- Added `setDmChatId` mutation to persist DM chat associations
- Added `openDirectMessage` action: creates or reuses a backing chat for each member DM
- Updated `selectTeam` and `createTeam` to reset DM state too

**`src/views/TeamView.vue`**
- Added **Direct Messages** section in the sidebar below channels, collapsible
- Members show with `MemberAvatar` + status dot; clicking opens DM chat
- Added `activeDmChat` data field and `loadDmChat` method
- Added `activeDmMember` computed from store getter
- Added DM view in the main content area with member header showing status badge
- Members panel in channel view now also opens DM on click
- Replaced inline add-member form with `AddMemberDialog` component

